// Report Manager
let _errSelected = []; // image | audio | subtitle

function toggleError(){
  const modal = document.getElementById('errorModal');
  if (!modal) return;

  const isHidden = modal.style.display === '' || modal.style.display === 'none';

  if (isHidden){
    modal.style.display = 'block';
    // cho browser render xong rồi mới add .show để transition chạy
    requestAnimationFrame(() => {
      modal.classList.add('show');
    });
  } else {
    modal.classList.remove('show');
    // đợi transition 0.22s xong rồi mới display:none
    setTimeout(() => {
      modal.style.display = 'none';
    }, 230);
  }
}

// chọn một option
document.addEventListener('click', function(ev){
  const btn = ev.target.closest('.err-opt');
  if (!btn) return;

  const val = btn.getAttribute('data-value');

  // Nếu đã chọn → bỏ chọn
  if (_errSelected.includes(val)) {
    _errSelected = _errSelected.filter(i => i !== val);
    btn.classList.remove('active');
  } 
  // Nếu chưa chọn → chọn thêm
  else {
    _errSelected.push(val);
    btn.classList.add('active');
  }
});

// đóng khi click nền tối (không đóng khi bấm trong hộp)
document.addEventListener('click', function(ev){
  const modal = document.getElementById('errorModal');
  if (!modal || modal.style.display === 'none') return;
  if (ev.target === modal) toggleError();
});

function submitError(){
    const text = document.getElementById('errorText').value.trim();
    if (text.length < 2) {
    toastr.warning('Vui lòng nhập đoạn ngắn mô tả.', '', {
    timeOut: 1000,
    extendedTimeOut: 200
    });
    return;
  }
  // bắt buộc chọn ít nhất 1 loại lỗi
  if (_errSelected.length === 0){
    toastr.warning('Vui lòng chọn ít nhất 1 vấn đề.', '', {
    timeOut: 1000,
    extendedTimeOut: 200
    });
    return;
  }

  const errorTextEl = document.getElementById('errorText');
  const errorText   = ((errorTextEl && errorTextEl.value) || '').trim();

  // Map value → label tiếng Việt
  const typeLabelsMap = {
    image: 'Hình ảnh',
    audio: 'Âm thanh',
    subtitle: 'Ngôn ngữ / Phụ đề'
  };

  // Chuyển ['image','audio'] → ['Hình ảnh','Âm thanh']
  const selectedLabels = _errSelected.map(v => typeLabelsMap[v] || v);

  // Tạo prefix: [Hình ảnh] hoặc [Hình ảnh, Âm thanh]
  const prefix = selectedLabels.length
    ? '[' + selectedLabels.join(', ') + ']'
    : '';

  // Gộp prefix + mô tả
  // Nếu user không nhập gì thì chỉ gửi "[Hình ảnh]"
  const finalMessage = errorText
    ? prefix + ': ' + errorText
    : prefix;

  // Gửi AJAX – CHỈ GỬI message
  $.ajax({
    url: URL_POST_REPORT,
    method: 'POST',
    headers: {
      "Content-Type": "application/json",
      "X-CSRF-TOKEN": document.querySelector('meta[name="csrf-token"]').content
    },
    dataType: 'json',
    data: JSON.stringify({
      message: finalMessage   // ví dụ: "[Hình ảnh, Âm thanh]: bị lệch tiếng"
    })
  })
  .done(function () {
    toastr.success('Cảm ơn bạn! Báo lỗi đã được ghi nhận.', '', {
    timeOut: 1000,
    extendedTimeOut: 200
    });

    // reset textarea & selections
    if (errorTextEl) errorTextEl.value = '';
    _errSelected = [];
    document.querySelectorAll('.err-opt.active').forEach(el => el.classList.remove('active'));

    // đóng modal
    toggleError();
  })
  .fail(function () {
    toastr.error('Không thể gửi báo lỗi. Vui lòng thử lại!.', '', {
    timeOut: 1000,
    extendedTimeOut: 200
    });
    console.log('error-connection');
  });
}